import './Favoritos.css';
import { useState, useEffect } from 'react';

function Favoritos() {
  const [filmes, setFilmes] = useState([]);

  useEffect(() => {
    const minhaLista = localStorage.getItem("@primeflix");
    if (minhaLista) {
      setFilmes(JSON.parse(minhaLista)  || []);
    }
  }, []);

  return (
    <div>
      <h1>Meus Filmes</h1>
    </div>
  );
}

export default Favoritos;
